parameters.jsCode:
const body = $input.first().json.body || $input.first().json;
const lead = {
  prenom: (body.prenom || '').trim(),
  nom: (body.nom || '').trim(),
  email: (body.email || '').trim().toLowerCase(),
  telephone: (body.telephone || '').trim(),
  type_travaux: (body.type_travaux || body.travaux || '').trim(),
  description: (body.description || body.message || '').trim(),
  adresse_chantier: (body.adresse_chantier || body.adresse || '').trim(),
  budget_estime: body.budget_estime || body.budget || null,
  delai_souhaite: body.delai_souhaite || body.delai || null,
  source: body.source || 'webhook',
  received_at: new Date().toISOString()
};
if (!lead.email || !lead.nom) {
  throw new Error('Lead invalide : email ou nom manquant');
}
return [{ json: lead }];

