parameters.jsCode:
const leadData = $('Parser Données Lead').first().json;
const aiResponse = $input.first().json;
let qualification;
try {
  qualification = JSON.parse(aiResponse.choices[0].message.content);
} catch(e) {
  qualification = { score: 'C', type_travaux_normalise: leadData.type_travaux, urgence: 'normale', complet: false, raison_incomplete: 'Erreur parsing IA' };
}
return [{ json: { ...leadData, ...qualification } }];

