parameters.jsCode:
const lead = $('Merger Lead + Qualification').first().json;
let emailBody = '';
try {
  const qualified = $('IA — Email Lead Qualifié').first();
  emailBody = qualified.json.choices[0].message.content;
} catch(e) {
  try {
    const incomplete = $('IA — Email Infos Manquantes').first();
    emailBody = incomplete.json.choices[0].message.content;
  } catch(e2) {
    emailBody = `Bonjour ${lead.prenom},\n\nNous avons bien reçu votre demande et reviendrons vers vous très rapidement.\n\nL'équipe`;
  }
}
const subject = lead.complet
  ? `Suite à votre demande — ${lead.type_travaux_normalise || lead.type_travaux}`
  : `Votre demande de devis — quelques précisions`;
return [{ json: { ...lead, email_subject: subject, email_body: emailBody } }];

